generetiOperatorText.guide:
{
  "format": "genereti-guide",
  "id": "feedback-reference-chain",
  "steps": [
    {
      "target": {
        "nodeType": "GeneretiTextureExpression",
        "part": "node",
        "ref": "e9268263-602c-4fa2-bf03-da37e327fb2d"
      },
      "text": "The expression draws fresh white dots on opaque black. This branch goes directly to the composite image input.",
      "title": "Fresh source"
    },
    {
      "target": {
        "nodeType": "GeneretiTextureFeedbackRef",
        "part": "node",
        "ref": "819225ac-3df1-4ccb-a9ba-5c193c022bfc"
      },
      "text": "top.feedbackref picks the final composite as its reference. It copies that output on the GPU and exposes it on the next graph tick. No cyclic IMAGE cable is needed. The optional image input seeds the first frame; otherwise it begins transparent.",
      "title": "Read the previous final image"
    },
    {
      "target": {
        "nodeType": "GeneretiTextureMath",
        "part": "node",
        "ref": "5c0d6588-d57f-4e81-9e0e-20484c85d035"
      },
      "text": "Multiply RGB by 0.96 to fade older marks. Try 0 to remove trails or 0.99 for longer history. Alpha is preserved, so decay affects visible brightness.",
      "title": "Decay the history"
    },
    {
      "target": {
        "nodeType": "GeneretiTextureTransform",
        "part": "node",
        "ref": "73642cfc-0b9a-40f4-82d6-6a635c7283f6"
      },
      "text": "Transform the preceding composite before mixing it with fresh dots. You can insert blur, corner pin or other processors anywhere along this branch.",
      "title": "Process the delayed frame"
    },
    {
      "target": {
        "nodeType": "GeneretiTextureComposite",
        "part": "node",
        "ref": "ba61e572-ddfe-4eb3-a191-dec5acd32c19"
      },
      "text": "Screen combines fresh dots with transformed history: black lets the trails show through. Over would cover history because this source is opaque. The reference targets this final composite; picking the original source instead gives a one-frame delay without recursive accumulation.",
      "title": "Composite with the source"
    },
    {
      "target": {
        "nodeType": "GeneretiLiveImagePreview",
        "part": "node",
        "ref": "397ab396-3a65-48cc-9180-961661b283f3"
      },
      "text": "Alt-W opens the final view; Alt-F fills the window. For a convenient single-node effect use top.feedback, which retains its own history and offers screen/add/over. Convert the reference STRING field to an input to drive it from a primitive or DAT. Camera, screen and audio still require explicit activation.",
      "title": "Perform and experiment"
    }
  ],
  "title": "A flexible feedback loop",
  "version": 1,
  "summary": "Use a delayed node reference to make a flexible recursive GPU feedback chain."
}

